import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame, ballSpeed, WIDTH, HEIGHT } from './game/neon.js';

const dummyCtx = {
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1: Ball should bounce off top of brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // top-left brick
  // Position ball just above the brick, moving down
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 2, r: 7, vx: 0, vy: 100 };

  // Simulate a frame.
  // Since we don't have a 'step' here (physics is in step, collision in frame)
  // we move the ball manually to trigger the collision in frame.
  state.ball.y += state.ball.vy * 0.016; // move slightly into the brick

  frame(dummyCtx, state);

  assert.ok(!brick.alive, 'Brick should be destroyed');
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP (vy < 0)');
});

test('D2: Ball should not stick to brick (must be pushed out)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball deeply inside the brick
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + 2, r: 7, vx: 0, vy: 100 };

  frame(dummyCtx, state);

  // After collision, ball should be outside the brick
  const stillColliding = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
    state.ball.y - state.ball.r < brick.y + brick.h
  );
  assert.equal(stillColliding, false, 'Ball should be repositioned outside the brick after bounce');
});

test('D3: Ball should not flip twice at a seam', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1]; // adjacent brick
  // Position ball at the seam of two bricks
  state.ball = { x: b1.x + b1.w, y: b1.y + b1.h / 2, r: 7, vx: 100, vy: 0 };

  frame(dummyCtx, state);

  // It should hit and bounce once, not twice (which would return it to vx > 0)
  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT (vx < 0)');
});

test('D4: Tunneling - Ball should not pass through at high speed', () => {
  const state = createState(6); // level 6
  const brick = state.bricks[0];
  const speed = ballSpeed(6);
  const dt = 0.05;

  // Position ball just above the brick
  state.ball = { x: brick.x + brick.w / 2, y: brick.y - 5, r: 7, vx: 0, vy: speed };

  // Move the ball by one big step (tunneling case)
  state.ball.y += state.ball.vy * dt; 
  // ball.y is now brick.y - 5 + 710 * 0.05 = 30.5. 
  // Brick.y = 48. Ball.r = 7. 
  // Let's check: brick.y is 48. Ball.y + r = 30.5 + 7 = 37.5. 
  // Still hasn't reached it.
  // Let's put it closer.

  state.ball.y = brick.y - 2; // just above
  state.ball.y += state.ball.vy * dt; // 46 + 35.5 = 81.5.
  // Brick bottom is 48 + 20 = 68.
  // Ball.y - r = 81.5 - 7 = 74.5.
  // The ball is now completely BELOW the brick.

  frame(dummyCtx, state);

  assert.ok(!brick.alive, 'Brick should have been hit even with tunneling');
});

