  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball deeply inside the brick
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + 2, r: 7, vx: 0, vy: 100 };

  frame(dummyCtx, state);

  // After collision, ball should be outside the brick
  const stillColliding = (
    state.ball.x + state.ball.r > brick.x &&
    state.ball.x - state.ball.r < brick.x + brick.w &&
    state.ball.y + state.ball.r > brick.y &&
