// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // --- Brick collisions (moved from frame for correctness and tunneling support) ---
  // We check collisions before moving to handle cases where the ball is already
  // overlapping, and again after moving to handle standard collisions.
  // To support tunneling, we also check if the ball's trajectory crossed a brick.

  const resolveBrick = (brick) => {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    const dx1 = ball.x + ball.r - brick.x;
    const dx2 = brick.x + brick.w - (ball.x - ball.r);
    const dy1 = ball.y + ball.r - brick.y;
    const dy2 = brick.y + brick.h - (ball.y - ball.r);

    const overlapX = Math.min(dx1, dx2);
    const overlapY = Math.min(dy1, dy2);

    if (overlapX < overlapY) {
      ball.vx *= -1;
      ball.x += (dx1 < dx2 ? -overlapX : overlapX);
    } else if (overlapY < overlapX) {
      ball.vy *= -1;
      ball.y += (dy1 < dy2 ? -overlapY : overlapY);
    } else {
      ball.vx *= -1;
      ball.vy *= -1;
      ball.x += (dx1 < dx2 ? -overlapX : overlapX);
      ball.y += (dy1 < dy2 ? -overlapY : overlapY);
    }
  };

  // 1. Initial overlap check (handles "sticky" and "seam" start cases)
  for (const brick of state.bricks) {
    if (brick.alive && collides(ball, brick)) {
      resolveBrick(brick);
      // After one brick is resolved, we can stop or continue. 
      // For the "seam" test, we must ensure we don't flip twice.
      // The repositioning usually prevents subsequent collisions in the same frame.
    }
  }

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // 2. Final overlap check (standard collision)
  for (const brick of state.bricks) {
    if (brick.alive && collides(ball, brick)) {
      resolveBrick(brick);
    }
  }

  // 3. Tunneling check (for very fast balls)
  // If the ball didn't collide but its trajectory crossed a brick, we resolve it.
  // This is a simplified swept check: if the ball's bounds shifted by more than 
  // its own size + brick size, we check if it jumped over.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    // Check if the ball's bounding box over the step overlaps the brick
    const minX = Math.min(ball.x - ball.vx * dt, ball.x) - ball.r;
    const maxX = Math.max(ball.x - ball.vx * dt, ball.x) + ball.r;
    const minY = Math.min(ball.y - ball.vy * dt, ball.y) - ball.r;
    const maxY = Math.max(ball.y - ball.vy * dt, ball.y) + ball.r;

    if (maxX > brick.x && minX < brick.x + brick.w && maxY > brick.y && minY < brick.y + brick.h) {
      // It crossed the brick's space. If it's not currently colliding, it tunneled.
      if (!collides(ball, brick)) {
        resolveBrick(brick);
      }
    }
  }

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

